-- --- TÁBLÁK LÉTREHOZÁSA (Ha még nem léteznek) ----- 1. Országok tábla (countries)CREATE TABLE countries (    id INT(11) PRIMARY KEY AUTO_INCREMENT,    name VARCHAR(100) NOT NULL UNIQUE);-- 2. Megyék/Államok tábla (states)CREATE TABLE states (    id INT(11) PRIMARY KEY AUTO_INCREMENT,    country_id INT(11) NOT NULL,    name VARCHAR(100) NOT NULL,    FOREIGN KEY (country_id) REFERENCES countries(id));-- 3. Utcák/Helyszínek tábla (streets)CREATE TABLE streets (    id INT(11) PRIMARY KEY AUTO_INCREMENT,    state_id INT(11) NOT NULL,    name VARCHAR(255) NOT NULL,    FOREIGN KEY (state_id) REFERENCES states(id));-- --- Teszt Adatok beszúrása ----- Országok (countries) - 5 bejegyzésINSERT INTO countries (name) VALUES ('Magyarország'), ('Németország'), ('USA'), ('Franciaország'), ('Japán');-- Megyék/Államok (states) - 2 országra már volt adat, azokat megtartva:-- 1. Magyarország (ID: 1)INSERT INTO states (country_id, name) VALUES(1, 'Pest'),             -- ID 1(1, 'Fejér'),            -- ID 2(1, 'Borsod-Abaúj-Zemplén'); -- ID 3-- 2. Németország (ID: 2)INSERT INTO states (country_id, name) VALUES(2, 'Bajorország'),      -- ID 4(2, 'Észak-Rajna-Vesztfália'); -- ID 5-- 3. USA (ID: 3)INSERT INTO states (country_id, name) VALUES(3, 'New York'),         -- ID 6(3, 'California');       -- ID 7-- 4. Franciaország (ID: 4)INSERT INTO states (country_id, name) VALUES(4, 'Île-de-France'),    -- ID 8(4, 'Provence-Alpes-Côte d\'Azur'); -- ID 9-- 5. Japán (ID: 5)INSERT INTO states (country_id, name) VALUES(5, 'Tokió'),            -- ID 10(5, 'Oszaka');           -- ID 11-- Utcák/Helyszínek (streets)-- Magyarország (ID: 1, 2, 3)INSERT INTO streets (state_id, name) VALUES-- Pest megye (state_id=1)(1, 'Kossuth Lajos utca (Budakeszi)'),(1, 'Fő utca (Szentendre)'),(1, 'Petőfi Sándor utca (Gödöllő)'),-- Fejér megye (state_id=2)(2, 'Rákóczi utca (Székesfehérvár)'),(2, 'Honvéd utca (Dunaújváros)'),-- Borsod-Abaúj-Zemplén 